{
  "id": "openmm-market-data",
  "configSchema": {
    "type": "object",
    "properties": {
      "exchange": { "type": "string", "enum": ["mexc", "gateio", "kraken", "bitget"] },
      "apiKey": { "type": "string" },
      "secretKey": { "type": "string" }
    }
  },
  "uiHints": {
    "apiKey": { "label": "Exchange API Key", "sensitive": true },
    "secretKey": { "label": "Exchange Secret Key", "sensitive": true }
  }
}

{
  "name": "@qbtlabs/openmm-market-data",
  "version": "0.1.0",
  "description": "Market data, portfolio tracking, and Cardano DEX integration for OpenMM",
  "keywords": ["openmm", "market-data", "portfolio", "cardano", "dex", "agent-skills"],
  "files": ["skills", "references", "openclaw.plugin.json", "CLAUDE.md", "README.md"],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/QBT-Labs/OpenMM-ai.git",
    "directory": "packages/plugins/openmm-market-data"
  },
  "dependencies": {
    "@3rd-eye-labs/openmm": "latest"
  }
}
